async def export(pool, remote, batches):
    async with pool.connection() as conn:
        task = asyncio.create_task(remote.send_batches(conn, batches))
        try:
            return await task
        except asyncio.CancelledError:
            task.cancel()
            try:
                await task
            except BaseException:
                pass
            raise

